export const SAMPLE_RATE = 44_100;
export const MIN_NOTE_HZ = 27.5;
export const MAX_NOTE_HZ = 4_186.009_044_809_578;
export const MAX_DURATION_SECONDS = 30;
export const REALTIME_BLOCK_SIZE = 128;
export const MAX_REALTIME_VOICES = 256;

const MAX_SAMPLES = SAMPLE_RATE * MAX_DURATION_SECONDS;
const WASM_BYTES = Uint8Array.from(atob(''), (character) => character.charCodeAt(0));
const WASM_MODULE = new WebAssembly.Module(WASM_BYTES);

function instantiateWasm() { const wasm = new WebAssembly.Instance(WASM_MODULE).exports; wasm._initialize(); return wasm; }
function copySamples(output, source, count) { let index = 0; for (; index + 3 < count; index += 4) { output[index] = source[index]; output[index + 1] = source[index + 1]; output[index + 2] = source[index + 2]; output[index + 3] = source[index + 3]; } for (; index < count; index += 1) output[index] = source[index]; }

const WASM = instantiateWasm();
const WASM_OUTPUT = new Float32Array(WASM.memory.buffer, WASM.output_ptr(), MAX_SAMPLES);

export function createGrandPianoProcessorOptions(polyphony) { return { polyphony, wasmModule: WASM_MODULE }; }

function requireFiniteNumber(name, value) {
 if (typeof value !== 'number' || !Number.isFinite(value)) throw new TypeError(`${name} must be a finite number`);
}

function requireUnsignedInteger(name, value) { requireFiniteNumber(name, value); if (!Number.isInteger(value) || value < 0 || value > 0xffff_ffff) throw new RangeError(`${name} must be an unsigned 32-bit integer`); }
function requireDelayFrames(value) { requireUnsignedInteger('delay_frames', value); }

export function synthesizeGrandPiano(note_hz, velocity, duration_seconds, output) {
 requireFiniteNumber('note_hz', note_hz); requireFiniteNumber('velocity', velocity); requireFiniteNumber('duration_seconds', duration_seconds);
 const sampleCount = Math.round(Math.min(MAX_DURATION_SECONDS, Math.max(0, duration_seconds)) * SAMPLE_RATE);
 if (output === undefined) output = new Float32Array(sampleCount);
 else if (!(output instanceof Float32Array) || output.length < sampleCount) throw new RangeError(`output must hold at least ${sampleCount} Float32 samples`);
 if (sampleCount === 0) return output;
 const rendered = WASM.synthesize(note_hz, velocity, duration_seconds);
 copySamples(output, WASM_OUTPUT, rendered);
 return output;
}

export function synthesizeGrandPianoInto(output, note_hz, velocity, duration_seconds) { return synthesizeGrandPiano(note_hz, velocity, duration_seconds, output); }

export function createRealtimeGrandPianoEngine(polyphony = 32) {
 requireFiniteNumber('polyphony', polyphony); const voiceLimit = Math.max(1, Math.min(MAX_REALTIME_VOICES, Math.trunc(polyphony))); const wasm = instantiateWasm(); const realtimeOutput = new Float32Array(wasm.memory.buffer, wasm.rt_output_ptr(), REALTIME_BLOCK_SIZE), realtimeLeft = new Float32Array(wasm.memory.buffer, wasm.rt_output_left_ptr(), REALTIME_BLOCK_SIZE), realtimeRight = new Float32Array(wasm.memory.buffer, wasm.rt_output_right_ptr(), REALTIME_BLOCK_SIZE); let engine;
 engine = {
  reset(sampleRate = SAMPLE_RATE) { requireFiniteNumber('sample_rate', sampleRate); if (wasm.rt_reset(sampleRate, voiceLimit) !== 0) throw new RangeError('sample_rate must be between 32000 and 96000 Hz'); return engine; },
  noteOn(id, note_hz, velocity, delay_frames = 0) { requireUnsignedInteger('id', id); requireFiniteNumber('note_hz', note_hz); requireFiniteNumber('velocity', velocity); requireDelayFrames(delay_frames); if (wasm.rt_note_on(id, note_hz, velocity, delay_frames) !== 0) throw new RangeError('realtime event queue is full'); return engine; },
  noteOff(id, release_velocity = 64 / 127, delay_frames = 0) { requireUnsignedInteger('id', id); requireFiniteNumber('release_velocity', release_velocity); requireDelayFrames(delay_frames); if (wasm.rt_note_off(id, release_velocity, delay_frames) !== 0) throw new RangeError('realtime event queue is full'); return engine; },
  sustain(position, delay_frames = 0) { const lift = typeof position === 'boolean' ? Number(position) : position; requireFiniteNumber('sustain_position', lift); requireDelayFrames(delay_frames); if (wasm.rt_sustain(lift, delay_frames) !== 0) throw new RangeError('realtime event queue is full'); return engine; },
  unaCorda(position, delay_frames = 0) { const shift = typeof position === 'boolean' ? Number(position) : position; requireFiniteNumber('una_corda_position', shift); requireDelayFrames(delay_frames); if (wasm.rt_una_corda(shift, delay_frames) !== 0) throw new RangeError('realtime event queue is full'); return engine; },
  keyPosition(id, position, speed = 64 / 127, delay_frames = 0) { requireUnsignedInteger('id', id); requireFiniteNumber('key_position', position); requireFiniteNumber('key_speed', speed); requireDelayFrames(delay_frames); if (wasm.rt_key_position(id, position, speed, delay_frames) !== 0) throw new RangeError('realtime event queue is full'); return engine; },
  process(output, frameCount = output.length) { if (!(output instanceof Float32Array)) throw new TypeError('output must be a Float32Array'); requireUnsignedInteger('frame_count', frameCount); if (frameCount > REALTIME_BLOCK_SIZE || output.length < frameCount) throw new RangeError(`output must hold 0..${REALTIME_BLOCK_SIZE} frames`); const rendered = wasm.rt_process(frameCount); if (rendered !== frameCount) throw new Error('realtime Wasm process failed'); copySamples(output, realtimeOutput, rendered); return output; },
  processStereo(left, right, frameCount = Math.min(left.length, right.length)) { if (!(left instanceof Float32Array) || !(right instanceof Float32Array)) throw new TypeError('left and right must be Float32Array channels'); requireUnsignedInteger('frame_count', frameCount); if (frameCount > REALTIME_BLOCK_SIZE || left.length < frameCount || right.length < frameCount) throw new RangeError(`channels must hold 0..${REALTIME_BLOCK_SIZE} frames`); const rendered = wasm.rt_process(frameCount); if (rendered !== frameCount) throw new Error('realtime Wasm process failed'); copySamples(left, realtimeLeft, rendered); copySamples(right, realtimeRight, rendered); return left; },
  activeVoiceCount() { return wasm.rt_voice_count(); },
  isNoteActive(id) { requireUnsignedInteger('id', id); return wasm.rt_note_active(id) !== 0; },
  get sampleRate() { return wasm.rt_sample_rate(); },
  get voiceLimit() { return wasm.rt_voice_limit(); },
  get voiceCapacity() { return wasm.rt_voice_capacity(); },
 };
 return engine.reset(SAMPLE_RATE);
}

export function renderGrandPianoNote(note_hz, velocity, key_down_seconds, { releaseVelocity = 64 / 127, sampleRate = SAMPLE_RATE, maximumTailSeconds = 30 } = {}) {
 requireFiniteNumber('note_hz', note_hz); requireFiniteNumber('velocity', velocity); requireFiniteNumber('key_down_seconds', key_down_seconds); requireFiniteNumber('release_velocity', releaseVelocity); requireFiniteNumber('sample_rate', sampleRate); requireFiniteNumber('maximum_tail_seconds', maximumTailSeconds);
 const gateFrames = Math.round(Math.min(MAX_DURATION_SECONDS, Math.max(0, key_down_seconds)) * sampleRate), maximumFrames = gateFrames + Math.round(Math.min(MAX_DURATION_SECONDS, Math.max(0, maximumTailSeconds)) * sampleRate); if (maximumFrames === 0 || velocity <= 0) return new Float32Array(0);
 const engine = createRealtimeGrandPianoEngine(1).reset(sampleRate), block = new Float32Array(REALTIME_BLOCK_SIZE), allocation = new Float32Array(maximumFrames); engine.noteOn(1, note_hz, velocity); let renderedFrames = 0, releaseQueued = false;
 while (renderedFrames < maximumFrames) { const blockFrames = Math.min(REALTIME_BLOCK_SIZE, maximumFrames - renderedFrames); if (!releaseQueued && gateFrames < renderedFrames + blockFrames) { engine.noteOff(1, releaseVelocity, gateFrames - renderedFrames); releaseQueued = true; } engine.process(block, blockFrames); allocation.set(block.subarray(0, blockFrames), renderedFrames); renderedFrames += blockFrames; if (releaseQueued && engine.activeVoiceCount() === 0) break; }
 if (engine.activeVoiceCount()) { const fadeSamples = Math.min(renderedFrames, Math.round(.05 * sampleRate)); for (let index = 0; index < fadeSamples; index += 1) allocation[renderedFrames - fadeSamples + index] *= .5 + .5 * Math.cos(Math.PI * index / (fadeSamples - 1 || 1)); }
 allocation[renderedFrames - 1] = 0;
 return renderedFrames === allocation.length ? allocation : allocation.slice(0, renderedFrames);
}

export default synthesizeGrandPiano;
